"""Documentacao da 230a leva. Uso: python docs.py"""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', 'engenharia-reversa'))
from gen_docs import fazer, leia, cadeia, prova_save, REF_JOGO, CARREIRA_PT, CARREIRA_EN

N = 230
R = [('gravar_continentes', 'db_files_write_continents', '0x54d6e0', 'Db_files.cpp', 'cdecl', 'grava a tabela continent.dat (id 3) de registros de 198 bytes de uma vez, por zwrite (save) ou fwrite (Data); 1 se foi tudo', 'writes the continent.dat (id 3) table of 198-byte records in one go, through zwrite (save) or fwrite (Data); 1 if everything went out'), ('gravar_nacoes', 'db_files_write_nations', '0x54d840', 'Db_files.cpp', 'cdecl', 'grava a tabela nation.dat (id 4) de registros de 290 bytes de uma vez, por zwrite (save) ou fwrite (Data); 1 se foi tudo', 'writes the nation.dat (id 4) table of 290-byte records in one go, through zwrite (save) or fwrite (Data); 1 if everything went out'), ('gravar_cidades', 'db_files_write_cities', '0x54d9a0', 'Db_files.cpp', 'cdecl', 'grava a tabela city.dat (id 21) de registros de 56 bytes de uma vez, por zwrite (save) ou fwrite (Data); 1 se foi tudo', 'writes the city.dat (id 21) table of 56-byte records in one go, through zwrite (save) or fwrite (Data); 1 if everything went out'), ('gravar_estadios', 'db_files_write_stadiums', '0x54daf0', 'Db_files.cpp', 'cdecl', 'grava a tabela stadium.dat de registros de 78 bytes de uma vez, por zwrite (save) ou fwrite (Data); 1 se foi tudo', 'writes the stadium.dat table of 78-byte records in one go, through zwrite (save) or fwrite (Data); 1 if everything went out'), ('gravar_clubes', 'db_files_write_clubs', '0x54e5d0', 'Db_files.cpp', 'cdecl', 'grava a tabela club.dat e nat_club.dat (ids 0, 1) de registros de 581 bytes de uma vez, por zwrite (save) ou fwrite (Data); 1 se foi tudo', 'writes the club.dat and nat_club.dat (ids 0, 1) table of 581-byte records in one go, through zwrite (save) or fwrite (Data); 1 if everything went out'), ('gravar_pessoas_110', 'db_files_write_staff', '0x54e720', 'Db_files.cpp', 'cdecl', 'grava a tabela staff.dat (pessoas, 110 bytes; id 6) de registros de 110 bytes de uma vez, por zwrite (save) ou fwrite (Data); 1 se foi tudo', 'writes the staff.dat (staff, 110 bytes; id 6) table of 110-byte records in one go, through zwrite (save) or fwrite (Data); 1 if everything went out'), ('gravar_nao_jogadores', 'db_files_write_players', '0x54efd0', 'Db_files.cpp', 'cdecl', 'grava a tabela dos não jogadores do staff.dat (id 9; o mapa da comunidade a chama de players) de registros de 68 bytes de uma vez, por zwrite (save) ou fwrite (Data); 1 se foi tudo', 'writes the staff.dat non-player (id 9; the community map calls it players) table of 68-byte records in one go, through zwrite (save) or fwrite (Data); 1 if everything went out'), ('gravar_jogadores', 'db_files_write_non_players', '0x54fbb0', 'Db_files.cpp', 'cdecl', 'grava a tabela dos jogadores do staff.dat (id 10; o mapa da comunidade a chama de non_players) de registros de 70 bytes de uma vez, por zwrite (save) ou fwrite (Data); 1 se foi tudo', 'writes the staff.dat player (id 10; the community map calls it non_players) table of 70-byte records in one go, through zwrite (save) or fwrite (Data); 1 if everything went out'), ('gravar_preferencias', 'db_files_write_staff_extra', '0x54fd00', 'Db_files.cpp', 'cdecl', 'grava a tabela das preferências das pessoas (id 22) de registros de 52 bytes de uma vez, por zwrite (save) ou fwrite (Data); 1 se foi tudo', 'writes the staff preferences (id 22) table of 52-byte records in one go, through zwrite (save) or fwrite (Data); 1 if everything went out')]
ESCAPADAS = {}  # nome: (explicação pt, explicação en), quando houver
tot, ac, esc, ok = cadeia(N)
assert ok, 'cadeia sem a referencia'
assert set(esc) <= set(ESCAPADAS), ('explicar as escapadas', esc)
lac_pt = ' '.join(f'`{e}` escapou: {ESCAPADAS[e][0]}.' for e in esc) + (' (lacuna em `PENDENCIAS.md`)' if esc else '')
lac_en = ' '.join(f'`{e}` escaped: {ESCAPADAS[e][1]}.' for e in esc) + (' (gap in `PENDENCIAS.en.md`)' if esc else '')
PS = prova_save(N)  # leva do save: mutações e prova pelo .qst gravado com e sem as rotinas (cadeia.sh)
VIA_PT = 'pela prova do save' if PS else 'pela carreira até 2002-06-01, confirmando no modo comparação as que escapam'
VIA_EN = 'by the save proof' if PS else 'by the career to 2002-06-01, confirming the escaped ones in comparison mode'
PS_PT = f'Prova do save (o .qst com e sem as rotinas): {PS}. ' if PS else ''
PS_EN = f'Save proof (the .qst with and without the routines): {PS.replace("IGUAL", "EQUAL").replace("DIFERENTE", "DIFFERENT")}. ' if PS else ''
M = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_PT}): {ac} acusadas. {lac_pt} {PS_PT}"
     f"Jogo real comparando até 2002-01-01: 0 divergências ({REF_JOGO}). Carreiras Rust ×2 e original até 2002-06-01: {CARREIRA_PT}")
ME = (f"`mutacoes/leva{N}.py` ({tot}, {VIA_EN}): {ac} caught. {lac_en} {PS_EN}"
      f"Real game comparing to 2002-01-01: 0 divergences ({REF_JOGO}). Rust ×2 and original careers to 2002-06-01: {CARREIRA_EN}")
fazer(N, 644, 644 + len(R), 'a gravação dos .dat: continentes, nações, cidades; a gravação dos .dat: estádios, clubes, pessoas 110; a gravação dos .dat: não jogadores, jogadores, preferências', 'writing the .dat files: continents, nations, cities; writing the .dat files: stadiums, clubs, staff 110; writing the .dat files: non-players, players, preferences',
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, d, _ in R],
      [f"| `{a}()` | {e} | {c} | {f}: {d} |" for a, _, e, f, c, _, d in R],
      M, ME, [(a, g) for a, g, *_ in R], "'posicao_no_conteiner': 'position_in_container',", secao=('Simulação', 'Simulation'))
leia(N, 'a gravação dos .dat: continentes, nações, cidades; a gravação dos .dat: estádios, clubes, pessoas 110; a gravação dos .dat: não jogadores, jogadores, preferências', 'writing the .dat files: continents, nations, cities; writing the .dat files: stadiums, clubs, staff 110; writing the .dat files: non-players, players, preferences', [(a, e, f + ', ' + c, dp, de) for a, _, e, f, c, dp, de in R], tot, ac, lac_pt, lac_en,
     campos=[('TContinent (198 bytes, [0xae23a4]): registro inteiro (+0xbe força regional, double); lê (gravar_continentes: vai para o arquivo)', 'TContinent (198 bytes, [0xae23a4]): whole record (+0xbe regional strength, double); reads (gravar_continentes: goes to the file)'), ('TNation (290 bytes, [0xae23a8]): registro inteiro (os rivais já trocados por índices pelo save_database); lê (gravar_nacoes)', 'TNation (290 bytes, [0xae23a8]): whole record (rivals already turned into indexes by save_database); reads (gravar_nacoes)'), ('TCities (56 bytes, [0xae23ac]): registro inteiro; lê (gravar_cidades)', 'TCities (56 bytes, [0xae23ac]): whole record; reads (gravar_cidades)'), ('TStadium (78 bytes): registro inteiro (+0x3c capacidade); lê (gravar_estadios)', 'TStadium (78 bytes): whole record (+0x3c capacity); reads (gravar_estadios)'), ('TClub (581 bytes, [0xae23b4 / 0xae23b8]): registro inteiro (ponteiros já trocados por índices); lê (gravar_clubes)', 'TClub (581 bytes, [0xae23b4 / 0xae23b8]): whole record (pointers already turned into indexes); reads (gravar_clubes)'), ('TStaff (110 bytes, [0xae23bc]): registro inteiro (ponteiros já trocados por índices); lê (gravar_pessoas_110)', 'TStaff (110 bytes, [0xae23bc]): whole record (pointers already turned into indexes); reads (gravar_pessoas_110)'), ('TNonPlayer (68 bytes, [0xae23c0]): registro inteiro; lê (gravar_nao_jogadores)', 'TNonPlayer (68 bytes, [0xae23c0]): whole record; reads (gravar_nao_jogadores)'), ('TPlayer (70 bytes, [0xae23c4]): registro inteiro; lê (gravar_jogadores)', 'TPlayer (70 bytes, [0xae23c4]): whole record; reads (gravar_jogadores)'), ('TPreferences (52 bytes, [0xae23c8]): registro inteiro; lê (gravar_preferencias)', 'TPreferences (52 bytes, [0xae23c8]): whole record; reads (gravar_preferencias)')], interessa=['SGE', 'CMRTE'])
